const input = $json ?? {};
return [{
  json: {
    triggerSource: 'workflow',
    noticeKey: input.notice_key ?? input.noticeKey ?? null,
    keyword: input.keyword ?? null,
    options: {
      dryRun: input.dry_run !== false,
      years: input.years ?? 3,
      pageSize: input.page_size ?? 100,
      maxPagesPerWindow: input.max_pages_per_window ?? 1
    }
  }
}];

const input = $json ?? {};
let apiBaseUrlRaw = '';
let envNoticeKey = '';
let envKeyword = '';
let liveEnabled = false;
try {
  apiBaseUrlRaw = String($env.PAI_LOOP_API_BASE_URL ?? '').trim();
  envNoticeKey = String($env.PAI_LOOP_AWARD_HISTORY_NOTICE_KEY ?? '').trim();
  envKeyword = String($env.PAI_LOOP_AWARD_HISTORY_KEYWORD ?? '').trim();
  liveEnabled = String($env.PAI_LOOP_LIVE_INGESTION_ENABLED ?? '').trim().toLowerCase() === 'true';
} catch {
  apiBaseUrlRaw = '';
  envNoticeKey = '';
  envKeyword = '';
  liveEnabled = false;
}
if (!apiBaseUrlRaw) throw new Error('PAI_LOOP_API_BASE_URL is required for protected award history refresh');
let parsedBaseUrl;
try { parsedBaseUrl = new URL(apiBaseUrlRaw); } catch {
  throw new Error('PAI_LOOP_API_BASE_URL must be an absolute HTTP(S) URL');
}
if (!['http:', 'https:'].includes(parsedBaseUrl.protocol) || parsedBaseUrl.username || parsedBaseUrl.password) {
  throw new Error('PAI_LOOP_API_BASE_URL must use HTTP(S) without embedded credentials');
}
const apiBaseUrl = parsedBaseUrl.toString().replace(/\/+$/, '');
const noticeKey = String(input.noticeKey ?? input.notice_key ?? envNoticeKey).trim();
if (!noticeKey || noticeKey.length > 160 || /[\/\u0000-\u001f\u007f]/.test(noticeKey)) {
  throw new Error('notice_key must be 1..160 characters without slash or control characters');
}
const options = input.options ?? {};
const years = Math.min(3, Math.max(1, Math.trunc(Number(options.years ?? 3))));
const pageSize = Math.min(100, Math.max(1, Math.trunc(Number(options.pageSize ?? 100))));
const maxPagesPerWindow = Math.min(3, Math.max(1, Math.trunc(Number(options.maxPagesPerWindow ?? 1))));
const keywordRaw = String(input.keyword ?? envKeyword ?? '').trim().replace(/\s+/g, ' ');
if (keywordRaw && (keywordRaw.length < 2 || keywordRaw.length > 100)) {
  throw new Error('keyword must be 2..100 characters when provided');
}
const requestedDryRun = options.dryRun !== false;
const dryRun = requestedDryRun || !liveEnabled;
const request = {
  years,
  page_size: pageSize,
  max_pages_per_window: maxPagesPerWindow,
  dry_run: dryRun,
  ...(keywordRaw ? { keyword: keywordRaw } : {})
};
const keyPart = noticeKey.replace(/[^a-zA-Z0-9가-힣._:-]/g, '_').slice(0, 60);
const keywordPart = keywordRaw
  ? keywordRaw.replace(/[^a-zA-Z0-9가-힣_-]/g, '_').slice(0, 24)
  : 'auto';
const today = new Date().toISOString().slice(0, 10);
return [{
  json: {
    runtime: {
      apiBaseUrl,
      triggerSource: input.triggerSource ?? 'unknown',
      liveEnabled,
      forcedDryRun: !requestedDryRun && !liveEnabled
    },
    noticeKey,
    endpointPath: `/api/v1/notices/${encodeURIComponent(noticeKey)}/award-history/refresh`,
    idempotencyKey: `award:${keyPart}:${today}:${years}y:${keywordPart}:${dryRun ? 'dry' : 'live'}`,
    request
  }
}];

const response = $json?.body && typeof $json.body === 'object' ? $json.body : $json;
if (!response || typeof response !== 'object' || Array.isArray(response)) {
  throw new Error('Award history response must be an object');
}
const allowedFields = new Set([
  'job_id', 'status', 'notice_key', 'keyword', 'window', 'api_calls', 'fetched',
  'created', 'updated', 'duplicates', 'records', 'dry_run', 'warnings'
]);
const unexpected = Object.keys(response).filter((field) => !allowedFields.has(field));
if (unexpected.length) {
  throw new Error(`Award history response contained unexpected field(s): ${unexpected.join(', ')}`);
}
for (const field of allowedFields) {
  if (!Object.prototype.hasOwnProperty.call(response, field)) {
    throw new Error(`Award history response is missing ${field}`);
  }
}
const requireString = (field, maxLength) => {
  const value = response[field];
  if (typeof value !== 'string' || !value || value.length > maxLength) {
    throw new Error(`${field} must be a non-empty string up to ${maxLength} characters`);
  }
  return value;
};
const requireCount = (field) => {
  const value = response[field];
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error(`${field} must be a non-negative safe integer`);
  }
  return value;
};
const windowValue = response.window;
if (!windowValue || typeof windowValue !== 'object' || Array.isArray(windowValue)) {
  throw new Error('window must be an object');
}
const windowKeys = Object.keys(windowValue);
if (windowKeys.length !== 2 || !windowKeys.includes('from') || !windowKeys.includes('to')) {
  throw new Error('window must contain only from/to');
}
const isoDate = /^\d{4}-\d{2}-\d{2}$/;
if (!isoDate.test(windowValue.from) || !isoDate.test(windowValue.to)) {
  throw new Error('window from/to must be YYYY-MM-DD');
}
if (windowValue.from > windowValue.to) throw new Error('window.from must not be after window.to');
const keyword = requireString('keyword', 100);
if (keyword.length < 2) throw new Error('keyword must be at least 2 characters');
if (typeof response.dry_run !== 'boolean') throw new Error('dry_run must be boolean');
if (!Array.isArray(response.warnings) || response.warnings.length > 20 ||
    !response.warnings.every((value) => typeof value === 'string' && value.length <= 500)) {
  throw new Error('warnings must be an array of at most 20 strings up to 500 characters');
}
const status = requireString('status', 16);
if (!['COMPLETED', 'PARTIAL'].includes(status)) {
  throw new Error('status must be COMPLETED or PARTIAL');
}
if (status === 'PARTIAL' && response.warnings.length === 0) {
  throw new Error('PARTIAL status requires at least one warning');
}
const counts = {
  apiCalls: requireCount('api_calls'),
  fetched: requireCount('fetched'),
  created: requireCount('created'),
  updated: requireCount('updated'),
  duplicates: requireCount('duplicates'),
  records: requireCount('records')
};
if (counts.records > counts.fetched) throw new Error('records must not exceed fetched');
return [{
  json: {
    schemaVersion: '1.0',
    jobId: requireString('job_id', 160),
    status,
    noticeKey: requireString('notice_key', 160),
    keyword,
    window: { from: windowValue.from, to: windowValue.to },
    counts,
    dryRun: response.dry_run,
    warnings: [...response.warnings],
    privacyBoundary: { candidateRowsEmitted: false, piiFieldsEmitted: false },
    completedAt: new Date().toISOString()
  }
}];
